   136  void *pj_dealloc_params (projCtx ctx, paralist *start, int errlev) {
   137  /*****************************************************************************
   138      Companion to pj_default_destructor (below). Deallocates a linked list
   139      of "+proj=xxx" initialization parameters.
   140
   141      Also called from pj_init_ctx when encountering errors before the PJ
   142      proper is allocated.
   143  ******************************************************************************/
