   172      /* TODO: we should probably have a public pj_cleanup() method to do all */
   173      /* that */
   174
   175      /* free the interface to Charles Karney's geodesic library */
   176      pj_dealloc( P->geod );
   177
   178      /* free parameter list elements */
   179      pj_dealloc_params (pj_get_ctx(P), P->params, errlev);
   180
   181      pj_dealloc (P->opaque);
   182      if (0!=errlev)
   183          pj_ctx_set_errno (pj_get_ctx(P), errlev);
   184      return pj_dealloc(P);
   185  }
